style.css:
/* === FULL BLACK TIKTOK THEME (Rodrygo Style) === */

/* Main background */
body, html {
  background-color: #000000 !important;
  color: #ffffff !important;
}

/* Main app container */
div[data-e2e="app"] {
  background-color: #000 !important;
}

/* Sidebar */
nav, aside {
  background-color: #050505 !important;
  border-right: 1px solid #111 !important;
}

/* Top bar */
header {
  background-color: #050505 !important;
  border-bottom: 1px solid #111 !important;
}

/* Video feed cards */
div[class*="DivItemContainer"] {
  background-color: #0a0a0a !important;
  border-radius: 12px !important;
  border: 1px solid #111 !important;
}

/* Buttons */
button {
  background-color: #d4af37 !important;
  color: #000 !important;
  border-radius: 8px !important;
  transition: all 0.2s ease !important;
}

button:hover {
  background-color: #f5d76e !important;
}

/* Text */
h1, h2, h3, p, span {
  color: #ffffff !important;
}

/* Secondary text */
span[class*="SpanTextSecondary"] {
  color: #aaaaaa !important;
}

/* Links */
a {
  color: #d4af37 !important;
}

a:hover {
  color: #f5d76e !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #000;
}

::-webkit-scrollbar-thumb {
  background: #222;
  border-radius: 10px;
}

/* Video overlay controls */
div[class*="DivActionItemContainer"] {
  background-color: rgba(0,0,0,0.6) !important;
  border-radius: 10px !important;
}

/* Glow effect (Rodrygo aura) */
button:hover, a:hover {
  box-shadow: 0 0 10px #d4af37, 0 0 20px #d4af37;
}

/* Inputs */
input, textarea {
  background-color: #0a0a0a !important;
  color: #fff !important;
  border: 1px solid #222 !important;
}

/* Remove bright backgrounds */
* {
  box-shadow: none !important;
}
